diff --git a/mailnews/imap/src/nsImapGenericParser.cpp b/mailnews/imap/src/nsImapGenericParser.cpp
index cd7125c3bc2..536a3811d91 100644
--- a/mailnews/imap/src/nsImapGenericParser.cpp
+++ b/mailnews/imap/src/nsImapGenericParser.cpp
@@ -173,9 +173,17 @@ void nsImapGenericParser::AdvanceTokenizerStartingPoint(
       fStartOfLineOfTokens[endTokenOffset] = fCurrentLine[endTokenOffset];
   }

-  NS_ASSERTION(bytesToAdvance + (fLineOfTokens - fStartOfLineOfTokens) <=
-                   (int32_t)strlen(fCurrentLine),
-               "cannot advance beyond end of fLineOfTokens");
+  // Enforce the bound. A caller that derived
+  // bytesToAdvance from a pointer that isn't in the tokenizer buffer would
+  // otherwise leave fLineOfTokens, and with it fCurrentTokenPlaceHolder,
+  // pointing at unrelated memory.
+  int32_t consumed = int32_t(fLineOfTokens - fStartOfLineOfTokens);
+  int32_t lineLength = fCurrentLine ? int32_t(strlen(fCurrentLine)) : 0;
+  if (bytesToAdvance < 0 || consumed < 0 || consumed > lineLength ||
+      bytesToAdvance > lineLength - consumed) {
+    SetSyntaxError(true, "cannot advance beyond end of fLineOfTokens");
+    return;
+  }
   fLineOfTokens += bytesToAdvance;
   fCurrentTokenPlaceHolder = fLineOfTokens;
 }
@@ -361,15 +369,28 @@ char* nsImapGenericParser::CreateLiteral() {
 // corresponding closing paren, and leave the parser in the right place
 // afterwards.
 char* nsImapGenericParser::CreateParenGroup() {
-  NS_ASSERTION(fNextToken[0] == '(', "we don't have a paren group!");
+  // Validate the precondition here rather than trusting the callers. At end of
+  // line AdvanceToNextToken() hands out the static CRLF literal, which is not
+  // in the tokenizer buffer, so subtracting fLineOfTokens from it would give a
+  // meaningless offset and move the tokenizer outside the line.
+  if (!fNextToken || fNextToken[0] != '(' || !fLineOfTokens) {
+    SetSyntaxError(true, "no paren group to create");
+    return nullptr;
+  }

   int numOpenParens = 0;
   AdvanceTokenizerStartingPoint(fNextToken - fLineOfTokens);
+  if (!ContinueParse()) return nullptr;

   // Build up a buffer containing the paren group.
   nsCString returnString;
   char* parenGroupStart = fCurrentTokenPlaceHolder;
-  NS_ASSERTION(parenGroupStart[0] == '(', "we don't have a paren group (2)!");
+  // AdvanceTokenizerStartingPoint() can bail out without advancing, leaving
+  // the tokenizer pointers null.
+  if (!parenGroupStart) {
+    SetSyntaxError(true, "tokenizer was reset in paren group");
+    return nullptr;
+  }
   while (*fCurrentTokenPlaceHolder) {
     if (*fCurrentTokenPlaceHolder == '{')  // literal
     {
diff --git a/mailnews/imap/src/nsImapServerResponseParser.cpp b/mailnews/imap/src/nsImapServerResponseParser.cpp
index 1dbb3d7ee54..de2ea44df11 100644
--- a/mailnews/imap/src/nsImapServerResponseParser.cpp
+++ b/mailnews/imap/src/nsImapServerResponseParser.cpp
@@ -1132,7 +1132,7 @@ void nsImapServerResponseParser::msg_fetch() {
       }
     } else if (!PL_strcasecmp(fNextToken, "X-GM-LABELS")) {
       AdvanceToNextToken();
-      if (!fNextToken)
+      if (!fNextToken || fNextToken[0] != '(')
         SetSyntaxError(true);
       else {
         fLabels = CreateParenGroup();
@@ -2277,8 +2277,11 @@ void nsImapServerResponseParser::id_data() {
   AdvanceToNextToken();
   if (!PL_strcasecmp(fNextToken, "NIL"))
     AdvanceToNextToken();
-  else
+  else if (fNextToken[0] == '(')
     fServerIdResponse.Adopt(CreateParenGroup());
+  // Anything else is a malformed id_response [RFC2971, Sec. 3.2]. The server
+  // ID is only informational, so don't fail the whole response over it, just
+  // leave fServerIdResponse unset.
   skip_to_CRLF();
 }

diff --git a/mailnews/imap/test/unit/test_imapIDNoParenGroup.js b/mailnews/imap/test/unit/test_imapIDNoParenGroup.js
new file mode 100644
index 00000000000..0b5dd2de1dd
--- /dev/null
+++ b/mailnews/imap/test/unit/test_imapIDNoParenGroup.js
@@ -0,0 +1,54 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+/*
+ * Regression test for an untagged ID response with no argument at all:
+ *
+ *   * ID<CR><LF>
+ *
+ * nsImapServerResponseParser::id_data() used to hand that to
+ * CreateParenGroup(), which assumed fNextToken pointed into the tokenizer
+ * buffer. At end of line AdvanceToNextToken() instead hands out the static
+ * CRLF literal, so the tokenizer got advanced by the distance between two
+ * unrelated objects and was then dereferenced (wild pointer read). Parsing
+ * such a response must now just be a syntax error, leaving the connection
+ * usable.
+ */
+
+/* import-globals-from ../../../test/resources/logHelper.js */
+load("../../../resources/logHelper.js");
+
+var { PromiseTestUtils } = ChromeUtils.importESModule(
+  "resource://testing-common/mailnews/PromiseTestUtils.sys.mjs"
+);
+
+add_setup(async function () {
+  setupIMAPPump("GMail");
+  // The fake server emits "* ID " + idResponse, so an empty response means the
+  // ID line carries no token after "ID".
+  IMAPPump.daemon.idResponse = "";
+
+  // Update the folder to kick start the ID exchange.
+  const promiseUrlListener = new PromiseTestUtils.PromiseUrlListener();
+  IMAPPump.inbox.updateFolderWithListener(null, promiseUrlListener);
+  await promiseUrlListener.promise;
+});
+
+add_task(async function updateInboxAgain() {
+  // A second update proves the connection and parser state survived parsing
+  // the malformed response (a corrupted parser would crash, fail or hang).
+  const promiseUrlListener = new PromiseTestUtils.PromiseUrlListener();
+  IMAPPump.inbox.updateFolderWithListener(null, promiseUrlListener);
+  await promiseUrlListener.promise;
+});
+
+add_task(function checkNoServerID() {
+  // Nothing parseable was sent, so no server ID should have been recorded.
+  Assert.ok(
+    !IMAPPump.incomingServer.serverIDPref,
+    "serverIDResponse pref should be unset after a malformed ID response"
+  );
+});
+
+add_task(teardownIMAPPump);
